 return `<h3>How to earn or find it</h3>${steps.length?`<ol class="unlock-steps">${steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol>`:`<p>${e((item.unlockSources||[]).join(' · ')||'The listing has no acquisition description.')}</p>`}${linked.map(comm=>`<div class="unlock-deed"><button class="text-link" data-commendation="${e(comm.id)}">${e(comm.name)} →</button><p>${e(comm.requirement)}</p></div>`).join('')}${guide?.cost?`<p class="guide-price">Purchase cost: <strong>${Number(guide.cost.amount).toLocaleString()} ${e(guide.cost.currency)}</strong></p>`:'<p class="fine-print">A purchase cost is shown only when the source confirms one.</p>'}${guide?.set?`<p>Set: ${e(guide.set.name)}</p>`:''}${!steps.length&&!linked.length?'<p class="fine-print">The source may require a shop purchase, time-limited event, promotion, or special unlock. Inspect its full guide before planning a grind.</p>':''}<a class="text-link" href="${e(safeURL(guide?.source||item.source))}" target="_blank" rel="noopener">Read the item’s source guide ↗</a>${guide?`<p class="fine-print">Acquisition detail checked ${e(String(guide.checkedAt||'').slice(0,10))}.</p>`:''}`;
